From 164482b4a910a83558e943a751478a356f090436 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:31:55 +0100
Subject: [PATCH] applets/taskmanager: switch to manual sorting when dragging a
 task

Dragging a task did nothing unless sorting was set to Manually, so tasks
sorted alphabetically or otherwise could never be rearranged by hand. A
drag now switches the widget to manual sorting, keeping the current order.

BUG: 342966
---
 applets/taskmanager/qml/MouseHandler.qml | 13 +++++++++----
 1 file changed, 9 insertions(+), 4 deletions(-)

diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..e56a2ac8f2 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -74,15 +74,20 @@ DropArea {
             ignoredItem = null;
         }

-        if (tasksModel.sortMode === TaskManager.TasksModel.SortManual && tasks.dragSource) {
+        if (tasks.dragSource) {
             // Reject drags between different TaskList instances.
             if (tasks.dragSource.parent !== above.parent) {
                 return;
             }

-            const insertAt = above.index;
+            if (tasks.dragSource !== above && tasks.dragSource.index !== above.index) {
+                // Switch to manual sorting via the config, keeping the current order.
+                if (tasksModel.sortMode !== TaskManager.TasksModel.SortManual) {
+                    Plasmoid.configuration.sortingStrategy = 1; // Manual
+                }
+
+                const insertAt = above.index;

-            if (tasks.dragSource !== above && tasks.dragSource.index !== insertAt) {
                 if (tasks.groupDialog) {
                     tasksModel.move(tasks.dragSource.index, insertAt,
                         tasksModel.makeModelIndex(tasks.groupDialog.visualParent.index));
@@ -93,7 +98,7 @@ DropArea {
                 ignoredItem = above;
                 ignoreItemTimer.restart();
             }
-        } else if (!tasks.dragSource && hoveredItem !== above) {
+        } else if (hoveredItem !== above) {
             hoveredItem = above;
             activationTimer.restart();
         }
